INSERT IGNORE INTO `headers` (`id`, `template_name`, `html_content`, `language_code`, `created_by`, `modified_by`, `created_at`, `modified_at`) VALUES (30, 'generateInvoiceZero', '<div class=\"row header mt-2 pt-2 mr-0 ml-0\">\r\n    <div style=\"width: 40%;\">\r\n        <div style=\"display: inline-block;vertical-align: top;width: 100%;text-align: left;\"\r\n            class=\"logo-image\">\r\n            <div class=\"wrap-logo\">\r\n                <img src=\"[reseller_logo]\">\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"width: 60%\" class=\"mr-0 ml-0\">\r\n        <div class=\"d-flex justify-content-end\">\r\n            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"></p>\r\n                    <p class=\"mb-0\">[company_name]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"></p>\r\n                    <p class=\"mb-0\">[contact_person]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"></p>\r\n                    <p class=\"mb-0\">[street] [house_number] [extention]<br />[zipcode] [place]</p>\r\n                </div>\r\n                \r\n                <div class=\"mb-0 d-flex space-span\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Factuur:</p>\r\n                    <p class=\"mb-0\">[invoice_number]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                        >Factuurdatum:\r\n                    </p>\r\n                    <p class=\"mb-0\">[date_of_today]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Vervaldatum: </p>\r\n                    <p class=\"mb-0\">[expiration_date]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                        >Contractnummer:\r\n                    </p>\r\n                    <p class=\"mb-0\">[contract_number]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Contractreferentie: </p>\r\n                    <p class=\"mb-0\">[contract_reference]</p>\r\n                </div>\r\n                <div class=\"mb-0 d-flex\">\r\n                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                        >Energie intermediair:</p\r\n                    >\r\n                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                        >[reseller_name]</p\r\n                    >\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', 'nl', 'admin', NULL, '2023-10-13 09:06:18', NULL);
